"""Weekly timesheet rows, one line of text per worker."""

from typing import Iterable, List
from collections import Counter

from hourglass.schedule import worker_minutes
from hourglass.models import Shift

def _check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has no worker name")

def _rank(row: tuple) -> tuple:
    return (-row[2], row[0])

def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, most hours first, then name."""
    shifts = list(shifts)
    _check_shifts(shifts)
    counts = Counter(shift.worker for shift in shifts)
    mins = worker_minutes(shifts)
    rows = [(key, counts[key], mins[key]) for key in counts]
    return [_line(*row) for row in sorted(rows, key=_rank)]

